import json
import serial
import time

# Update 'COM3' to match your actual ESP32 port (or your Wokwi virtual serial port)
PORT = 'COM3' 
BAUD = 115200

def send_latest_event():
    try:
        # 1. Read the latest event generated by pulse_bridge.py
        with open('pulse_events/latest_event.json', 'r') as f:
            data = json.load(f)

        # Extract the predicted class name (e.g., "short_horn_ahead")
        class_name = data['prediction']['class_name']
        print(f"Loaded from JSON -> Detected Class: {class_name}")

        # 2. Send over Serial to the ESP32
        ser = serial.Serial(PORT, BAUD, timeout=1)
        time.sleep(2) # Allow connection to settle
        
        # Send the class name followed by a newline character
        command = f"{class_name}\n"
        ser.write(command.encode('utf-8'))
        print(f"Successfully sent '{class_name.strip()}' to ESP32!")
        
        ser.close()
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    send_latest_event()
